fn write_number(stream:i32, value:u64)->i32 {
    var bytes:[u8;20] = make [u8;20] {
        0u8,0u8,0u8,0u8,0u8,0u8,0u8,0u8,0u8,0u8,
        0u8,0u8,0u8,0u8,0u8,0u8,0u8,0u8,0u8,0u8
    };
    var begin:usize = 20usize;
    while true {
        begin = begin - 1usize;
        bytes[begin] = 48u8 + ((value % 10u64) as u8);
        value = value / 10u64;
        if value == 0u64 { break; }
    }
    unsafe { return write_bytes(stream, &bytes[begin], 20usize - begin); }
}
